mapper.select:
select t.order_type orderType,t.reason,t.pay_time payTime,t.apply_person_name
applyPersonName,t.remark,t.status_cd statusCd,t.owner_id ownerId,t.refund_order_id
refundOrderId,t.payer_obj_name payerObjName,t.owner_name ownerName,t.audit_person_name
auditPersonName,t.audit_person_id auditPersonId,t.apply_person_id applyPersonId,t.state,t.community_id
communityId,t.payer_obj_type payerObjType,t.payer_obj_id payerObjId,t.create_time createTime,td.name stateName,
t.pay_order_id payOrderId
from refund_fee_order t
left join t_dict td on t.state = td.status_cd and td.table_name = 'return_pay_fee' and td.table_columns = 'state'
where 1 =1

    and t.order_type= #{orderType}


    and t.reason= #{reason}


    and t.pay_time= #{payTime}


    and t.apply_person_name= #{applyPersonName}


    and t.remark= #{remark}


    and t.status_cd= #{statusCd}


    and t.owner_id= #{ownerId}


    and t.refund_order_id= #{refundOrderId}


    and t.payer_obj_name= #{payerObjName}


    and t.owner_name= #{ownerName}


    and t.audit_person_name= #{auditPersonName}


    and t.audit_person_id= #{auditPersonId}


    and t.apply_person_id= #{applyPersonId}


    and t.state= #{state}


    and t.community_id= #{communityId}


    and t.payer_obj_type= #{payerObjType}


    and t.payer_obj_id= #{payerObjId}

order by t.create_time desc

    limit #{page}, #{row}

